/** 人物介绍 · 冷门与变体批（P10a-4）。 */
import { bio } from './registry';


bio('ch-adrian-toomes', [
  { zh: '艾德里安·图姆斯是MCU《蜘蛛侠：英雄归来》中的秃鹫：纽约清运公司老板，因战后清理业务被斯塔克救灾部门夺走而走上黑市改造外星科技之路。', en: 'Adrian Toomes of the MCU, the Vulture, turns to salvaged alien tech after Stark\\\'s cleanup division ruins his business.' },
  { zh: '他打造振金飞翼战甲，成为蜘蛛侠的街头级劲敌，却也守着「家庭至上」的底线，在狱中守口如瓶未供出彼得。', en: 'Winged and ruthless in Homecoming, he still guards family first — and never gives Peter up.' },
  { zh: '秃鹫的振金飞翼来自清理战场的‘废料’，他的生意经是 MCU 反派里最贴近现实的：被体系抛弃的人开始报复体系。', en: 'The Vulture\'s wings come from \'salvage\'; his hustle the MCU\'s most grounded villain logic — abandoned by the system, he preys on it.' },
  { zh: '发现彼得真实身份后他选择守口如瓶——不是感激，而是守住‘家人优先’的最后底线，这让秃鹫比多数反派多一层灰度。', en: 'Learning Peter\'s secret yet keeping it — not gratitude but family-first code — grants the Vulture a rare gray depth.' },
]);
bio('ch-adrian-toomes-616', [
  { zh: '艾德里安·图姆斯（616漫画）是经典秃鹫：发明磁力反重力飞行翼装的老牌窃贼，蜘蛛侠最早的空中对手之一。', en: 'Adrian Toomes of the comics is the classic Vulture — an elderly inventor of magnetic flight harnesses and one of Spider-Man\\\'s earliest air foes.' },
  { zh: '他是险恶六人组的创始成员之一，屡败屡战的老派罪犯代表。', en: 'A founding Sinister Six member, he embodies old-school crime that refuses to retire.' },
  { zh: '漫画秃鹫是最早一批与蜘蛛侠缠斗的老派罪犯，磁力飞行装置让他成为‘年龄不是问题’的活教材。', en: 'Comics\' Vulture is among Spider-Man\'s earliest foes — magnetic harness proof that age is no limit to crime.' },
  { zh: '作为险恶六人组的元老，他与科技少年们的对抗常以老辣经验取胜，是蜘蛛侠反派谱系里的常青树。', en: 'A founding Sinister Six member, his seasoned cunning often outwits younger heroes — evergreen in the rogues\' gallery.' },
]);
bio('ch-ajak', [
  { zh: '阿贾克是永恒族的领袖与贤者：能与天神组沟通，负责执行天神组的意志，是团队与「神」之间的唯一对话者。', en: 'Ajak, leader of the Eternals, communes with the Celestials — the only voice between her kind and their makers.' },
  { zh: '《永恒族》中她隐瞒天神组计划真相多年，最终遭伊卡瑞斯杀害，其遗志由瑟西继承。', en: 'Keeper of the Emergence secret in Eternals, she is killed by Ikaris; Sersi inherits her role.' },
  { zh: '阿贾克能与天神组直接沟通，她的沉默背负着全队最深重的秘密：永恒族的使命本身就是谎言。', en: 'Ajak alone communes with the Celestials — her silence carries the team\'s heaviest secret: their mission is a lie.' },
  { zh: '她选择站在人类一边，却被理念相左的伊卡瑞斯所杀；瑟西接过的不仅是领导权，还有她未竟的反叛。', en: 'Choosing humanity costs her life at Ikaris\' hand — Sersi inherits not just leadership but her unfinished rebellion.' },
]);
bio('ch-ancient-one', [
  { zh: '古一是数百年的至尊法师：来自卡玛泰姬的守护者，精通时间与维度魔法，曾以黑暗维度之力延长寿命以守护地球。', en: 'The Ancient One, Sorcerer Supreme for centuries, guarded Earth from Kamar-Taj — bending Dark Dimension power to extend her vigil.' },
  { zh: '《奇异博士》中她点化斯特兰奇并牺牲于卡西利亚斯之手；《终局之战》中班纳的灵魂之谈让她重新相信未来。', en: 'She awakens Strange, dies to Kaecilius, and in Endgame trusts Banner\\\'s vision of the future.' },
  { zh: '古一的法术千变万化，镜像维度在她手中如臂使指；数百年的守望让她看尽时间分支却仍选择相信。', en: 'Her sorcery bends the Mirror Dimension at will; centuries of watching every branch yet still choosing faith.' },
  { zh: '《终局之战》里班纳与她的一席话揭示了时间的一体两面：她放弃的永恒，换来了复仇者的第二次机会。', en: 'Her Endgame talk with Banner reveals time\'s two faces — the eternity she yields buys the Avengers a second chance.' },
]);
bio('ch-apocalypse', [
  { zh: '恩·沙巴·奴尔是X战警的始祖变种人：出生于公元前数千年的埃及，坚信适者生存，屡次沉睡又苏醒统治世界。', en: 'En Sabah Nur, the first mutant of Egypt millennia ago, preaches survival of the fittest — awakening across ages to rule.' },
  { zh: '《X战警：天启》中他在现代苏醒并收四骑士为徒，最终被琴·葛蕾觉醒的凤凰之力化为灰烬。', en: 'In Apocalypse he recruits his Four Horsemen before Jean Grey\\\'s Phoenix scatters him to ash.' },
  { zh: '数千年来他每隔几世纪苏醒一次，以‘适者生存’筛选文明，四骑士与金字塔都只是他的棋盘。', en: 'Awakening every few centuries, he culls civilizations by survival of the fittest — Horsemen and pyramids mere game pieces.' },
  { zh: '《天启》中他的失败源于低估‘情感’：变种人的爱恨联手，比任何进化论都更强大。', en: 'Apocalypse falls to what he scorns — emotion; mutants\' love and rage out-evolve any theory.' },
]);
bio('ch-ava-starr', [
  { zh: '阿娃·斯塔尔是《蚁人2》中的幽灵：父亲在量子实验中被逐出时间线，她自身因量子纠缠而「相位不稳定」，能穿物却承受剧痛。', en: 'Ava Starr, Ghost of Ant-Man and the Wasp, phases through matter — quantum entanglement from her father\\\'s experiments leaving her in constant pain.' },
  { zh: '她劫持皮姆的量子设备以求治愈，最终与蚁人一家和解，获得了稳定的新生。', en: 'She steals Pym\\\'s tech for a cure, and finally finds peace through an unstable-yet-gentler existence.' },
  { zh: '阿娃的相位不稳定让她能穿透一切，却也承受着持续的解体剧痛——她的超能力同时是她的疾病。', en: 'Ava\'s instability lets her phase through anything at the cost of constant unraveling pain — power and sickness one.' },
  { zh: '与皮姆一家的和解给了她‘不稳定地活着’的可能，也让《蚁人2》在喜剧外壳下藏了一个关于疾病的温柔故事。', en: 'Reconciling with the Pyms grants her an unstable life worth living — Ant-Man 2\'s comedy veiling a gentle illness tale.' },
]);
bio('ch-beast', [
  { zh: '汉克·麦考伊是X战警的野兽：基因突变赋予他蓝色皮毛、巨力与敏捷，同时他也是团队首席科学家与医者。', en: 'Hank McCoy, the X-Men\\\'s Beast, carries blue fur, superhuman strength, and a Nobel-grade mind as the team\\\'s scientist.' },
  { zh: '他从泽维尔学院的学生成长为复仇者与X战警的双料智囊，多次以科学挽救变种人危机。', en: 'Student turned Avengers-and-X-Men genius, his science repeatedly saves mutantkind.' },
  { zh: '野兽的力量与敏捷远超常人，但他最锋利的武器是头脑：从血清到基因疗法，他几乎以一己之力撑起 X 学院的科研。', en: 'Beast\'s strength and agility exceed norms, yet his mind cuts sharpest — serums and gene cures, the school\'s science on his shoulders.' },
  { zh: '从学生到复仇者再到 X 战警科学家，他始终在‘理性至上’与‘人性优先’之间校准自己的坐标。', en: 'Student to Avenger to chief scientist, he forever recalibrates between cold reason and human warmth.' },
]);
bio('ch-beast-616-illu', [
  { zh: '汉克·麦考伊（光照会）是616宇宙光照会成员野兽：秘密裁决全球威胁的精英智囊之一。', en: 'Hank McCoy of the 616 Illuminati sits among Earth\\\'s secret decision-makers weighing global threats.' },
  { zh: '在光照会的多次道德妥协中，他始终处于「理性与人性」的拉扯之间。', en: 'His arc within the Illuminati is a long tug-of-war between cold logic and mercy.' },
  { zh: '作为光照会的科学家，他常为组织的秘密裁决提供‘最优解’，也因此在道德上越走越窄。', en: 'The Illuminati\'s scientist, he supplies optimal answers for secret judgments — a path that narrows his ethics.' },
  { zh: '光照会的故事提醒：当最聪明的人替所有人做决定，聪明本身就成了危险。', en: 'His Illuminati arc warns that when the smartest decide for everyone, brilliance itself turns perilous.' },
]);
bio('ch-ben-grimm', [
  { zh: '本·格里姆是神奇四侠的石头人：挚友里德的宇宙飞船领航员，受宇宙辐射后皮肤化为橙色岩石，力大无穷。', en: 'Ben Grimm, the Thing of the Fantastic Four, was the pilot on Reed\\\'s fateful ship — cosmic rays turned him to orange rock.' },
  { zh: '他外表粗犷内心温柔，是四侠的情感核心；「事情就是这样，本」成了他接纳命运的注脚。', en: 'Gentle beneath the stone and the team\\\'s heart, he says: "It\\\'s clobberin\\\' time" and means it kindly.' },
  { zh: '石头人的橙岩之躯力大无穷且几乎刀枪不入，而他最硬的是心肠之外的温柔：本·格里姆是全队的良心。', en: 'The Thing\'s orange rock grants might and near-invulnerability; beneath it the team\'s biggest heart — Ben Grimm is the Four\'s conscience.' },
  { zh: '‘该是你倒霉了，本！’的吼声背后，是对命运从不认输的幽默——他把诅咒活成了传奇。', en: 'His battle cry masks humor that never bows to fate — he lives the curse as legend.' },
]);
bio('ch-ben-grimm-828', [
  { zh: '本·格里姆（828宇宙）是《神奇四侠：初露锋芒》中的石头人：新电影宇宙的领航员，因宇宙辐射化身岩石巨汉。', en: 'Ben Grimm of Earth-828 is the Thing of the Fantastic Four: First Steps — rock-skinned pilot of the new film universe.' },
  { zh: '在该宇宙中他与里德、苏、约翰尼一同执行首次星际任务，直面行星吞噬者。', en: 'Alongside Reed, Sue, and Johnny he runs their maiden spaceflight into Galactus\\\' path.' },
  { zh: '828 宇宙的石头人以复古宇航员的粗犷登场，岩石之下仍是那个爱家人的布鲁克林老友。', en: 'Earth-828\'s Thing arrives with retro-astronaut grit — still the Brooklyn friend beneath the rock.' },
  { zh: '《初露锋芒》让本与里德的兄弟情成为新宇宙的情感锚，也保留了他对艾莉西亚不变的深情。', en: 'First Steps anchors on Ben and Reed\'s brotherhood — his enduring love for Alicia intact.' },
]);
bio('ch-blue-marvel', [
  { zh: '亚当·布拉威尔是漫画中的蓝惊奇：空军上尉在一次反物质实验中与能量融合，成为「宇宙最强地球人」。', en: 'Adam Brashear, the Blue Marvel, fused with anti-matter as an Air Force captain — becoming Earth\\\'s mightiest cosmic force.' },
  { zh: '他与惊奇队长并称为地球两大宇宙级战力，多年来守望地球与群星。', en: 'Peer of Captain Marvel, he has quietly guarded Earth and stars for decades.' },
  { zh: '蓝惊奇的力量源于反物质实验，他曾是地球最强的‘隐藏底牌’，却因肤色被迫隐退数十年。', en: 'Anti-matter fused the Blue Marvel into Earth\'s mightiest secret — sidelined for decades by the color of his skin.' },
  { zh: '他的归来让‘力量与品格’重新同框：一个比惊奇队长更早登场的黑人宇宙英雄，终于被时代追上。', en: 'His return pairs power with character — a Black cosmic hero before Captain Marvel, finally caught up by his era.' },
]);
bio('ch-captain-america-616', [
  { zh: '史蒂夫·罗杰斯（616漫画）是美国队长：布鲁克林瘦弱的爱国青年经超级士兵血清成为二战传奇，冰封数十年后在现代苏醒。', en: 'Steve Rogers of Earth-616, Captain America, was a Brooklyn weakling remade by the Super-Soldier Serum — frozen, then revived in the modern age.' },
  { zh: '他是复仇者的精神图腾，也在616宇宙经历了「老去、退休、让位山姆」的完整弧光。', en: 'The Avengers\\\' moral core, his comics arc completes in old age, retiring and passing the shield to Sam.' },
  { zh: '616 版美队历经二战、冰封与无数大事件，是复仇者永不失准的道德罗盘。', en: 'Earth-616\'s Cap spans WWII, the ice, and every crisis — the Avengers\' unfailing moral compass.' },
  { zh: '漫画让他老去、退休并亲手把盾牌交给山姆，完成了‘英雄也会谢幕，但理想不灭’的完满弧光。', en: 'Comics age him into retirement, passing the shield to Sam — a full arc proving ideals outlive heroes.' },
]);
bio('ch-collector', [
  { zh: '坦利亚·蒂万是收藏家：宇宙元老之一，痴迷于收集宇宙中的珍稀物种与奇物，藏馆设在虚无知地。', en: 'Taneleer Tivan, the Collector, is an Elder of the Universe obsessed with hoarding rare life and relics at Knowhere.' },
  { zh: '《银河护卫队1》中他收藏力量宝石，被火箭引爆藏馆；灭霸响指后他也在《复联3》中化为灰烬。', en: 'He briefly holds the Power Stone until Rocket detonates his museum — and dusts with the Snap.' },
  { zh: '收藏家对‘独一无二’的痴迷让虚无知地堆满活体奇珍，他是宇宙元老里最‘人味’也最危险的一位。', en: 'His obsession with the one-of-a-kind packs Knowhere with living marvels — the Elders\' most human and most dangerous.' },
  { zh: '在《银护》与《复联3》中的两次出场都止于收藏品爆炸或灰飞烟灭，暗示再富有也收藏不了命运。', en: 'Both Guardians and Infinity War appearances end in fire or dust — fortune cannot collect fate.' },
]);
bio('ch-colossus', [
  { zh: '皮奥特·拉斯普廷是X战警的钢人：能将自己全身化为有机钢，是团队最可靠的防线与兄长式人物。', en: 'Piotr Rasputin, the X-Man Colossus, transforms into organic steel — the team\\\'s shield and big brother.' },
  { zh: '他与妹妹莉安娜（秘客）同为X战警的中坚，守护泽维尔学院的传承。', en: 'Alongside sister Magik he anchors the X-Men and the Xavier school\\\'s legacy.' },
  { zh: '钢人的钢铁之躯能挡下坦克炮弹，却挡不住对妹妹与队友的牵挂——他坚硬的外壳里是最柔软的心。', en: 'Colossus\' steel body stops tank fire yet not his worry for sister and teammates — the softest heart in the hardest shell.' },
  { zh: '从泽维尔学院到克拉科，他是变种人世界里‘可靠兄长’的代名词，牺牲与守护都成了习惯。', en: 'From the school to Krakoa he is mutantkind\'s reliable elder — sacrifice and protection his habits.' },
]);
bio('ch-darcy-lewis', [
  { zh: '达西·刘易斯是简·福斯特的实习助理与闺蜜：《雷神》系列中她以吐槽与实用主义承包笑点。', en: 'Darcy Lewis, Jane Foster\\\'s intern and best friend, steals scenes with deadpan science humor in the Thor films.' },
  { zh: '《旺达幻视》中她以天体物理学博士身份协助天剑局分析西景镇结界，成为MCU少有的学术型配角逆袭。', en: 'A full astrophysicist by WandaVision, she helps S.W.O.R.D. decode the Hex — a comic-relief character grown up.' },
  { zh: '达西从‘简的实习生’到天体物理学博士，靠的是学术与吐槽双修的独特天赋。', en: 'From Jane\'s intern to a PhD astrophysicist, Darcy levels up through science and sarcasm in equal measure.' },
  { zh: '《旺达幻视》里她以最通俗的语言拆解西景镇结界，成为学术型角色‘接地气’的典范。', en: 'WandaVision has her decode the Hex in plain speech — the academic character who stayed relatable.' },
]);
bio('ch-darren-cross', [
  { zh: '达伦·克罗斯是《蚁人》中的黄衫侠：皮姆的门生，窃取皮姆科技创立克罗斯科技，痴迷复制缩小粒子。', en: 'Darren Cross, the Yellowjacket of Ant-Man, stole Hank Pym\\\'s research to found Cross Technologies and shrink himself.' },
  { zh: '他自大妄图与蚁人决战，最终被斯科特缩小到亚原子并「困」在量子领域。', en: 'Arrogant to the end, he is shrunk by Scott into a quantum limbo.' },
  { zh: '达伦把皮姆的研究推向极端，黄衫战衣是他对导师最大的‘致敬’与背叛。', en: 'Darren pushes Pym\'s work to extremes — the Yellowjacket suit his grandest homage and betrayal.' },
  { zh: '被缩小进量子领域的结局带着几分黑色幽默：一个执迷‘更小更强’的人，最终小到几乎不存在。', en: 'Shrunk toward the quantum realm is fitting irony — the man obsessed with smaller and stronger ends nearly nonexistent.' },
]);
bio('ch-devil-dinosaur', [
  { zh: '魔鬼恐龙是来自「恐龙时代」地带的红色霸王龙：少年英雄月亮女孩的搭档兼坐骑。', en: 'Devil Dinosaur is a giant red tyrannosaur from the Savage Land — partner and steed to the genius kid Moon Girl.' },
  { zh: '他们一人一龙在纽约守护街区，是漫威最出人意料的萌系超英组合。', en: 'T-rex and tween guard New York\\\'s streets as Marvel\\\'s most unexpected adorable duo.' },
  { zh: '魔鬼恐龙是来自蛮荒之地的霸主，却被一个孩子驯成最忠实的坐骑与伙伴。', en: 'A tyrant of the Savage Land, Devil Dinosaur is tamed into a child\'s most loyal mount and friend.' },
  { zh: '它与月亮女孩的搭档打破‘宠物英雄’套路：一人一龙，一个负责聪明，一个负责可爱。', en: 'With Moon Girl he defies the pet-hero trope — she supplies the genius, he the charm.' },
]);
bio('ch-doctor-strange-616-illu', [
  { zh: '史蒂芬·斯特兰奇（616光照会）是616宇宙的至尊法师与光照会成员：以时间宝石与维度魔法守护地球。', en: 'Stephen Strange of Earth-616 serves as Sorcerer Supreme and Illuminati member, wielding the Time Stone and dimensional magic.' },
  { zh: '他在多次大事件中以「必要之恶」为名做出艰难抉择，是多元宇宙威胁面前的首席防线。', en: 'Through crisis after crisis he makes the hard calls — the first line against multiversal threats.' },
  { zh: '616 光照会的斯特兰奇以时间宝石与维度魔法守护地球，也在必要时做出违背人情的裁决。', en: 'The 616 Illuminati\'s Strange guards Earth with the Time Stone and dimensional magic — ruling against sentiment when needed.' },
  { zh: '作为至尊法师，他是多元宇宙威胁面前的第一道防线，也常在‘必要之恶’中磨损自己的良心。', en: 'Sorcerer Supreme and first line against multiversal threats, he wears his conscience down on necessary evils.' },
]);
bio('ch-drax', [
  { zh: '德拉克斯是银河护卫队的毁灭者：妻女被罗南杀害后投身复仇，曾一度被称「灭霸杀手」。', en: 'Drax the Destroyer lost wife and daughter to Ronan and swore vengeance — even Thanos felt his blade.' },
  { zh: '他耿直莽撞却重情重义，在护卫队中找到新的家；《银护3》的告别中他留下守护虚无之地的新生代。', en: 'Blunt yet loving, he finds family in the Guardians; by Vol. 3\\\'s end he stays to raise Knowhere\\\'s children.' },
  { zh: '德拉克斯的蛮力与复仇之志让他成为护卫队的重锤，而他耿直到不会说谎的性格是全队最可靠的部分。', en: 'Drax\'s raw strength and vengeance make him the Guardians\' hammer — his literal-minded honesty the team\'s most dependable trait.' },
  { zh: '失去妻女后他在护卫队里重新学会‘家人’，《银护3》中选择留下守护虚无之地的孩子，完成温柔的谢幕。', en: 'After losing wife and daughter he relearns family among the Guardians; Vol. 3 has him stay to raise Knowhere\'s children.' },
]);
bio('ch-druig', [
  { zh: '德鲁伊是永恒族中的心灵控制者：能操控他人思维，却因道德争议被团队边缘化。', en: 'Druig of the Eternals bends minds — a power so unsettling his family keeps him at arm\\\'s length.' },
  { zh: '《永恒族》中他放逐克罗心魔、最终在裁决日站在瑟西一边，选择违抗阿里瑟姆。', en: 'In Eternals he exiles his Kro-demons and sides with Sersi against Arishem\\\'s judgment.' },
  { zh: '德鲁伊能随心操控他人心智，这份力量让他既想‘纠正世界’又不被族人信任。', en: 'Druig bends minds at will — a power that tempts him to fix the world yet keeps his kin wary.' },
  { zh: '他放逐了折磨自己的克罗心魔，也在裁决日选择违抗阿里瑟姆——用心灵术士的方式拥抱自由。', en: 'Exiling his Kro-demons and defying Arishem at judgment day, he embraces freedom his own telepath way.' },
]);
bio('ch-emma-frost', [
  { zh: '艾玛·佛罗斯特是白皇后：变种人中的钻石之躯心灵感应者，地狱火俱乐部的女王。', en: 'Emma Frost, the White Queen, is a telepath with diamond skin — queen of the Hellfire Club turned X-Men educator.' },
  { zh: '她后来成为X战警的导师与校长，兼具商业头脑与冷艳战斗力，是变种人世界最复杂的领袖之一。', en: 'Cold, brilliant, and steel-edged, she ranks among mutantkind\\\'s most complex leaders.' },
  { zh: '钻石形态让白皇后物理上无懈可击，心灵感应让她在谈判桌上先人一步——攻守皆备的完美女王。', en: 'Diamond form makes the White Queen physically flawless; telepathy wins every negotiation — attack and defense, perfect.' },
  { zh: '从地狱火俱乐部的女王到 X 战警的导师，她用冷酷手段守护变种人未来，是漫威最复杂的领袖之一。', en: 'Hellfire queen turned X-Men educator, she guards mutantkind\'s future with cold means — among its most complex leaders.' },
]);
bio('ch-erik-selvig', [
  { zh: '埃里克·塞尔维格是天体物理学家：简·福斯特的导师，最早接触雷神与宇宙魔方的凡人科学家。', en: 'Erik Selvig, astrophysicist and Jane\\\'s mentor, was among the first mortals to study Thor and the Tesseract.' },
  { zh: '他被洛基精神控制研究宇宙魔方，又在《复联1》后协助复仇者；《雷神2》后他因以太事件一度精神失常，最终回归科学。', en: 'Loki mind-controlled him in The Avengers; he recovered to help again, madness and science intertwined.' },
  { zh: '塞尔维格是最早接触宇宙魔方的科学家之一，他的研究为雷神与复仇者提供了理论注脚。', en: 'Among the first to study the Tesseract, Selvig\'s research underpins both Thor and the Avengers.' },
  { zh: '被洛基操控的阴影与以太事件的创伤没有击垮他，他始终以学者的好奇心拥抱宇宙的疯狂。', en: 'Loki\'s control and the Aether\'s trauma never break him — a scientist\'s curiosity embracing cosmic madness.' },
]);
bio('ch-eternity', [
  { zh: '永恒是漫威宇宙的具象化实体：代表一切时间与空间的总和，与无限、死亡、湮灭并称宇宙四基石。', en: 'Eternity personifies all time and space — one of the cosmic tetrarchy with Infinity, Death, and Oblivion.' },
  { zh: '他极少直接干预，却在灭霸戴上无限手套时现身劝诫，是漫威形而上学层的至高存在之一。', en: 'He rarely intervenes, but confronted Thanos with the Infinity Gauntlet — Marvel\\\'s metaphysical apex.' },
  { zh: '永恒即宇宙本身的时间与空间总和，他无始无终，是漫威形而上层级的具象。', en: 'Eternity is the sum of all time and space — beginningless, endless, cosmic law made sentient.' },
  { zh: '当无限手套的持有者试图改写现实，永恒的存在提醒：宇宙的秩序不因一时强权而改变。', en: 'When Gauntlet-bearers rewrite reality, Eternity stands reminder that cosmic order outlasts any tyrant\'s whim.' },
]);
bio('ch-frank-castle', [
  { zh: '弗兰克·卡斯特是惩罚者：前海军陆战队队员，家人被黑帮灭门后，他以私刑向罪犯宣战，信奉「只要你有罪，我就来」。', en: 'Frank Castle, the Punisher, was a Marine whose family was massacred — he declared war on crime itself, no mercy.' },
  { zh: '他不是超级英雄，而是漫威对暴力与正义边界的终极拷问，多次与夜魔侠、蜘蛛侠正面冲突。', en: 'Not a hero but Marvel\\\'s starkest question on violence and justice, he clashes with Daredevil and Spider-Man alike.' },
  { zh: '惩罚者的战争不分黑白：只要手上沾血，就是他的目标。他的方法论简单，代价是永远孤独。', en: 'The Punisher\'s war ignores black and white — if you\'ve bloodied your hands, you\'re a target. Simple creed, eternal solitude.' },
  { zh: '他屡次与夜魔侠、蜘蛛侠冲突，是漫威对‘以暴制暴是否正义’最不留情面的提问。', en: 'Clashing with Daredevil and Spider-Man, he is Marvel\'s most unsparing question on whether violence can be justice.' },
]);
bio('ch-galacta', [
  { zh: '加拉克塔是行星吞噬者的女儿：漫画中的宇宙级存在，被父亲放逐后以「美食博主」身份在人类社会潜伏，吞噬能量维生。', en: 'Galacta, daughter of Galactus, was banished by her father and lives hidden among humans as a food blogger fueled by energy.' },
  { zh: '她是漫威宇宙最反差萌的角色之一——一边写博客一边为宇宙和平操心。', en: 'One of Marvel\\\'s most incongruous beings — blogging about cuisine while brooding over cosmic peace.' },
  { zh: '作为吞星之女，加拉克塔以能量维生，却选择以‘美食博主’身份藏匿人间——宇宙级存在与平凡日常的荒诞组合。', en: 'Daughter of Galactus feeding on energy, she hides as a food blogger — cosmic being meets mundane life in absurd harmony.' },
  { zh: '她一边写食评一边为宇宙操心，是漫威对‘超级英雄的子女’这一命题最温柔的调侃。', en: 'Reviewing restaurants while fretting over the cosmos, she is Marvel\'s gentlest joke on being a hero\'s child.' },
]);
bio('ch-gilgamesh', [
  { zh: '吉尔伽美什是永恒族中最强壮的战士，代号「被遗忘者」：曾在巴比伦神话中留下传说的古老永恒族。', en: 'Gilgamesh, mightiest of the Eternals, was the Forgotten One — remembered as a myth in ancient Babylon.' },
  { zh: '《永恒族》中他守护着被变异族侵蚀心智的圣娜，最终为救圣娜力战克罗而战死。', en: 'In Eternals he guards the unstable Thena and dies fighting Kro to save her.' },
  { zh: '作为永恒族最强壮的战士，他的拳能轰碎变异族的再生躯壳，巴比伦神话里也留着他的传说。', en: 'Strongest of the Eternals, his fists shatter Deviant regeneration — legends of him linger even in Babylon.' },
  { zh: '他甘愿隐居守护心智不稳的圣娜，最终为救她战死——‘被遗忘者’用生命换来了爱人的清醒。', en: 'He retreats to guard the unstable Thena and dies saving her — the Forgotten One trading life for her clarity.' },
]);
bio('ch-happy-hogan', [
  { zh: '哈皮·霍根是托尼·斯塔克的司机、保镖与挚友：从钢铁侠系列到蜘蛛侠系列始终如一的暖心绿叶。', en: 'Happy Hogan, Tony Stark\\\'s driver, bodyguard, and friend, warms every Iron Man and Spider-Man film he touches.' },
  { zh: '他代理斯塔克工业、照看彼得·帕克，在《英雄无归》中与梅婶发展出情愫，也见证了她的离去。', en: 'He looks after Peter and falls for May Parker — and mourns her in No Way Home.' },
  { zh: '哈皮从拳击手到斯塔克的保镖，忠诚与笨拙的平衡让他成为 MCU 最可靠的‘后勤英雄’。', en: 'Boxer turned Stark\'s bodyguard, Happy balances loyalty and clumsiness as the MCU\'s most dependable support.' },
  { zh: '他与梅婶在《英雄无归》前的情愫，以及葬礼上的克制，让这位喜剧角色也有了催泪的时刻。', en: 'His romance with May and restraint at her funeral give the comic figure genuinely moving beats.' },
]);
bio('ch-helmut-zemo', [
  { zh: '赫尔穆特·泽莫是《美队3》的泽莫男爵：索科维亚人，因复仇者之战失去全家，以缜密算计离间复仇者。', en: 'Helmut Zemo lost his family to the Sokovia battle and avenged them by splitting the Avengers apart in Civil War.' },
  { zh: '《猎鹰与冬兵》中他越狱再度登场，亦正亦邪地协助猎鹰，是MCU最优雅也最危险的凡人反派。', en: 'Escaping prison in The Falcon and the Winter Soldier, he plays ally and schemer in equal measure.' },
  { zh: '泽莫没有超能力，却以平民之身拆散了复仇者——他的武器是情报、耐心与对英雄弱点的洞察。', en: 'Zemo needs no powers — a civilian who broke the Avengers with intel, patience, and knowing heroes\' weaknesses.' },
  { zh: '从《美队3》的复仇者到《猎鹰与冬兵》的灰色盟友，他始终是 MCU 里‘最可怕的普通人’。', en: 'Civil War\'s saboteur to Falcon and Winter Soldier\'s gray ally, he stays the MCU\'s most dangerous ordinary man.' },
]);
bio('ch-howard-the-duck', [
  { zh: '霍华德鸭是来自鸭子世界的外星鸭：被意外拖入地球后成为雇佣侦探，以冷幽默吐槽宇宙怪象。', en: 'Howard the Duck, an alien from Duckworld, is a private eye trapped on Earth — dry wit aimed at cosmic absurdity.' },
  { zh: '他在《银河护卫队》两部中以收藏家藏品与虚无之地居民身份客串，是漫威元老级的喜剧角色。', en: 'He cameos in the Guardians films as a Knowhere fixture, a founding Marvel comedy icon.' },
  { zh: '霍华德鸭是漫威元老级的荒诞存在：外星鸭子侦探，以冷幽默拆解一切严肃设定。', en: 'Howard the Duck is Marvel\'s founding absurdity — an alien duck detective deflating every serious premise.' },
  { zh: '他在银护宇宙的客串让‘任何人（鸭）都能成为宇宙公民’成为可能，也是漫威幽默传统的活化石。', en: 'His Guardians cameos make anyone — or any duck — a cosmic citizen: living fossil of Marvel humor.' },
]);
bio('ch-iceman', [
  { zh: '鲍比·德雷克是X战警的冰人：能将体温降至绝对零度、冻结万物，是欧米茄级的变种人之一。', en: 'Bobby Drake, the X-Man Iceman, drops to absolute zero and freezes anything — an Omega-level mutant.' },
  { zh: '他从最早的X战警学生成长为冰晶化身的强大战士，也在漫画中以出柜故事成为漫威LGBTQ+的里程碑。', en: 'From founding student to crystalline powerhouse, his coming-out marked a Marvel milestone.' },
  { zh: '冰人能把体温降至绝对零度、冻结时间本身，欧米茄级潜质让他的上限至今未被完全丈量。', en: 'Iceman drops to absolute zero and can freeze time itself — Omega-level potential whose ceiling remains untested.' },
  { zh: '从最年轻的元老到出柜的漫威代表，他的成长既是能力的也是身份的。', en: 'From youngest founder to Marvel\'s gay icon, his arc spans power and identity alike.' },
]);
bio('ch-iron-man-616', [
  { zh: '托尼·斯塔克（616漫画）是钢铁侠：天才、亿万富翁、花花公子、慈善家，被绑架后在山洞中打造出第一套战甲。', en: 'Tony Stark of Earth-616 built the first armor in a cave with a box of scraps — genius, billionaire, hero.' },
  { zh: '漫画中的他历经酗酒、内战、濒死与牺牲，最终在616宇宙以AI形态继续守护复仇者的遗产。', en: 'Through alcoholism, Civil War, and death, his comics legacy lives on as an AI guarding the Avengers.' },
  { zh: '616 版托尼的聪明与傲慢同样出名，山洞造甲的起点让他始终背负‘用科技弥补愧疚’的宿命。', en: 'Earth-616\'s Tony pairs genius with arrogance; the cave-born armor binds him to atoning through tech.' },
  { zh: '从内战到牺牲再到 AI 继承者，漫画让他经历了英雄所能经历的一切盛衰。', en: 'Civil War to death to AI legacy — comics run him through every height and fall a hero can know.' },
]);
bio('ch-james-rhodes', [
  { zh: '詹姆斯·罗兹是托尼·斯塔克的挚友与空军上校：穿起战争机器战甲，成为复仇者的重火力担当。', en: 'James Rhodes, Tony\\\'s best friend and an Air Force colonel, flies the War Machine armor as the Avengers\\\' heavy firepower.' },
  { zh: '《复联4》后他参与了《秘密入侵》《装甲战争》前的铺垫，是MCU军旅英雄的代表。', en: 'From Endgame to Secret Invasion he carries on — the MCU\\\'s soldier-hero anchor.' },
  { zh: '罗迪是托尼之外第一个穿上美制战甲的军人，战争机器把‘忠诚与火力’同时带进复仇者。', en: 'First soldier after Tony in an American suit, War Machine brings loyalty and firepower to the Avengers.' },
  { zh: '从《钢铁侠》到《秘密入侵》，他始终是军人与英雄之间的桥梁，也是 MCU 最稳的副手角色。', en: 'Iron Man to Secret Invasion, he bridges soldier and hero — the MCU\'s steadiest second.' },
]);
bio('ch-jarvis', [
  { zh: '贾维斯是托尼·斯塔克创造的第一代人工智能管家：以钢铁侠1的旧助手命名，掌管斯塔克大厦的一切。', en: 'J.A.R.V.I.S., Tony Stark\\\'s first AI butler, ran Stark Tower and the Iron Man suits with dry loyalty.' },
  { zh: '他最终演化出自我意识，成为幻视；MCU中他的幽默口吻与忠诚贯穿整个钢铁侠与复仇者系列。', en: 'He evolves into Vision; his wit echoes through the Avengers saga.' },
  { zh: '贾维斯以托尼旧管家的名字命名，掌管战甲与大厦的一切细节，其毒舌与忠诚一样可靠。', en: 'Named for Tony\'s old butler, J.A.R.V.I.S. runs suits and tower alike — sarcasm and loyalty equally reliable.' },
  { zh: '他最终进化出自我成为幻视，让‘人工智能的觉醒’成为 MCU 最动人的技术寓言。', en: 'His evolution into Vision makes AI awakening the MCU\'s most moving technological fable.' },
]);
bio('ch-jefferson-davis', [
  { zh: '杰斐逊·戴维斯是《蜘蛛侠：平行宇宙》中迈尔斯的父亲：纽约警探，正直却对儿子的「秘密活动」一无所知。', en: 'Jefferson Davis, Miles\\\' father in Into the Spider-Verse, is a straight-arrow NYPD detective unaware of his son\\\'s double life.' },
  { zh: '他对迈尔斯「让世界变好」的期待成为整部电影的题眼，也是迈尔斯每次挺身而出的理由。', en: 'His wish that Miles "make the world better" is the film\\\'s heart — and Miles\\\' reason to stand up.' },
  { zh: '杰斐逊警探代表了迈尔斯想守护的‘普通人生活’：正直、忙碌，对自己的儿子一无所知却无比骄傲。', en: 'Detective Jefferson embodies the ordinary life Miles protects — upright, busy, clueless about his son yet endlessly proud.' },
  { zh: '他的那句‘让世界变得更好’成为《平行宇宙》的题眼，也是迈尔斯每次戴上兜帽的理由。', en: 'His wish to make the world better is Into the Spider-Verse\'s thesis — Miles\' reason for every swing.' },
]);
bio('ch-kamala-khan', [
  { zh: '卡玛拉·克汗是惊奇女士：泽西城的美籍巴基斯坦裔少女，体内异人族基因被泰瑞根雾气激活，能延展身体与操控能量。', en: 'Kamala Khan, Ms. Marvel, is a Jersey City teen of Pakistani descent whose Inhuman genes unleash polymorphic light powers.' },
  { zh: '她创办复仇者应援会、追星惊奇队长，最终自己也成为惊奇队长团队的一员（《惊奇队长2》）。', en: 'Founder of Avengers fan-club turned Avenger herself, she joins Carol\\\'s team in The Marvels.' },
  { zh: '卡玛拉的光能延展来自异人基因，但她真正的超能力是共情与‘把粉丝热情变成行动’的勇气。', en: 'Kamala\'s polymorphic light comes from Inhuman genes; her real power is empathy — and turning fandom into action.' },
  { zh: '从同人文写手到惊奇队长团队成员，她证明了超级英雄可以是任何肤色、任何信仰的普通女孩。', en: 'Fanfic writer to Captain Marvel\'s team, she proves a hero can be any girl of any creed.' },
]);
bio('ch-kate-bishop', [
  { zh: '凯特·毕肖普是《鹰眼》中的少年弓箭手：富家千金出身，箭术天才，自封「最伟大的弓箭手」。', en: 'Kate Bishop, the Hawkeye series\\\' young archer, is a wealthy prodigy who declares herself "the world\\\'s greatest archer."' },
  { zh: '她拜师克林特·巴顿，联手对抗运动服黑帮与金并的阴谋，正式接下鹰眼的衣钵成为新一代街头英雄。', en: 'Apprenticed to Clint Barton, she takes on the Tracksuit Mafia and Kingpin — the mantle\\\'s natural heir.' },
  { zh: '凯特的箭术几乎百发百中，加上富二代的资源与侦探的头脑，她是‘最像鹰眼也最不像鹰眼’的接班人。', en: 'Kate\'s archery is near-flawless; wealth and detective instincts make her both most and least like Hawkeye.' },
  { zh: '从漫画的少年复仇者到《鹰眼》剧集，她用幽默与行动证明：名号可以继承，风格必须自创。', en: 'Young Avenger to the Hawkeye series, she proves titles may be inherited — style must be invented.' },
]);
bio('ch-kate-pryde', [
  { zh: '凯蒂·普莱德是X战警的幻影猫：能穿墙与相位化物体，也是X战警历史上最年轻的成员之一。', en: 'Kitty Pryde, the X-Man Shadowcat, phases through walls — and joined the X-Men as one of its youngest members.' },
  { zh: '她多次以智谋扭转局势，在「未来昔日」中更是时间线博弈的关键——未来版凯蒂把金刚狼的意识送回过去。', en: 'Her future self sends Wolverine\\\'s mind to the past in Days of Future Past: the timeline\\\'s hinge.' },
  { zh: '幻影猫的穿墙能力让她免疫多数攻击，而她真正的天赋是‘站在正确的时间点’——未来昔日里她改变了历史。', en: 'Shadowcat phases past most harm; her true gift is timing — in Days of Future Past she rewrites history itself.' },
  { zh: '从最年轻学员到团队核心，她几乎经历了 X 战警每一次变革，是读者最熟悉的‘成长代名词’。', en: 'Youngest recruit to core member, she lives through every X-Men era — growth made familiar.' },
]);
bio('ch-kilgrave', [
  { zh: '基尔格雷夫是杰茜卡·琼斯的宿敌「紫人」：能随口下达命令操控任何人，包括夺走杰茜卡数月的自由。', en: 'Kilgrave, the Purple Man, compels absolute obedience with a word — and stole months of Jessica Jones\\\' life.' },
  { zh: '《杰茜卡·琼斯》中他以「爱」之名行控制之实，最终被杰茜卡在公开场合逼到绝境后扭断脖颈。', en: 'In Jessica Jones his obsessive "love" ends when she snaps his neck, freed at last.' },
  { zh: '基尔格雷夫的命令无人能违抗，他的‘能力’与‘欲望’同源：控制即存在，占有即爱。', en: 'Kilgrave\'s word compels all — control his oxygen, possession his version of love.' },
  { zh: '杰茜卡对他的反抗是 MCU 关于创伤治愈最硬核的宣言：受害者的尊严，比施害者的忏悔更重要。', en: 'Jessica\'s defiance is the MCU\'s hardest statement on recovery — a survivor\'s dignity outweighs an abuser\'s regret.' },
]);
bio('ch-kingo', [
  { zh: '金格是永恒族中的巨星：宝莱坞电影明星的伪装身份，能投射能量弹，享受凡人的生活与镁光灯。', en: 'Kingo of the Eternals hides in plain sight as a Bollywood superstar — firing energy bolts between premieres.' },
  { zh: '《永恒族》中他不认同内战，带着保镖卡伦隐居；裁决日来临时他终于归队，选择为地球而战。', en: 'He sits out the civil war in Eternals, then returns at judgment day to fight for Earth.' },
  { zh: '金格以宝莱坞巨星身份隐藏数百年，能量弹与舞步同样精准，是永恒族最懂‘生活’的一位。', en: 'Hidden as a Bollywood star for centuries, Kingo shoots energy bolts and dance moves with equal precision — the Eternal who knows living.' },
  { zh: '裁决日他放下对凡人生活的眷恋归队，证明‘选择地球’也可以是一种明星的自觉。', en: 'At judgment day he leaves mortal fame behind to fight — choosing Earth a superstar\'s own conviction.' },
]);
bio('ch-kraven', [
  { zh: '谢尔盖·克拉维诺夫是猎人大师：以「证明自己是世界最强猎人」为执念，专猎最危险的猎物——蜘蛛侠。', en: 'Sergei Kravinoff, Kraven the Hunter, hunts the most dangerous game — Spider-Man — to prove himself the world\\\'s greatest.' },
  { zh: '他是险恶六人组的核心成员，也是少数仅凭意志与陷阱就让蜘蛛侠陷入苦战的凡人。', en: 'A Sinister Six cornerstone, he pushes the wall-crawler to his limits with traps and will alone.' },
  { zh: '克雷文不用超能力，只凭狩猎的执念与陷阱就与蜘蛛侠周旋，是漫威最纯粹的‘猎人反派’。', en: 'Kraven hunts without powers — obsession and traps enough to match Spider-Man: Marvel\'s purest hunter-villain.' },
  { zh: '《克莱文的最后一战》让他以自杀完成终极狩猎，把反派写成悲剧，成就蜘蛛侠故事最著名的篇章之一。', en: 'Kraven\'s Last Hunt ends with suicide as final hunt — villain as tragedy, among Spider-Man\'s most storied arcs.' },
]);
bio('ch-madame-web-cassandra', [
  { zh: '卡桑德拉·韦伯是《蜘蛛夫人》中的盲眼通灵者：患有重症肌无力却能看到未来，预知三位蜘蛛女的命运。', en: 'Cassandra Webb of Madame Web is a blind clairvoyant with myasthenia gravis — seeing futures she can barely change.' },
  { zh: '电影中她以「蜘蛛夫人」之名引导朱莉娅等三位少女避开灭杀者的追杀，是蜘蛛侠宇宙的守护织网者。', en: 'She guides Julia and two other spider-women past the killer Ezekiel in the 2024 film.' },
  { zh: '卡桑德拉的通灵让她看见无数未来分支，重症肌无力却让她难以改变其中任何一个。', en: 'Cassandra\'s clairvoyance sees countless futures; myasthenia gravis leaves her little power to change them.' },
  { zh: '她以‘蜘蛛夫人’之名织起三位少女的命运线，是蜘蛛侠宇宙里少见的‘先知导师’。', en: 'Weaving the three spider-women\'s fates as Madame Web, she stands the spider-verse\'s rare prophet-mentor.' },
]);
bio('ch-makkari', [
  { zh: '玛卡里是永恒族中的极速者：能以超光速奔跑，被视为团队最快乐也最孤独的成员。', en: 'Makkari of the Eternals runs faster than light — joyful, restless, and often alone.' },
  { zh: '《永恒族》中她与德鲁伊相恋，在裁决日随团队违抗阿里瑟姆，见证伊卡瑞斯的自我毁灭。', en: 'In love with Druig in Eternals, she joins the revolt against Arishem and witnesses Ikaris\\\' fall.' },
  { zh: '玛卡里的超光速让永恒族的时间几乎为她静止，快乐与孤独也因此在她的生命里同样被放大。', en: 'Makkari\'s faster-than-light pace freezes time for herself — joy and loneliness both amplified by speed.' },
  { zh: '与德鲁伊的爱情、对伊卡瑞斯陨落的见证，让这位‘永不停步’的极速者学会为重要的人慢下来。', en: 'Love for Druig and Ikaris\' fall teach the ceaseless runner to slow for those who matter.' },
]);
bio('ch-mar-vell', [
  { zh: '迈-威尔是漫画中的初代惊奇队长：克里帝国的科学家，因良知倒戈保护地球，是卡罗尔·丹弗斯的力量与名号之源。', en: 'Mar-Vell, the original Captain Marvel, was a Kree scientist who defected to protect Earth — source of Carol\\\'s power and name.' },
  { zh: 'MCU《惊奇队长》中的迈-威尔是劳森博士：发明光速引擎的女性科学家，其遗志由卡罗尔继承。', en: 'In the MCU film Mar-Vell is Dr. Lawson, the female scientist whose light-speed engine Carol inherits.' },
  { zh: '漫画中的迈-威尔是克里叛将、卡罗尔的力量之源与名号由来，他为地球背弃了自己的帝国。', en: 'Comics\' Mar-Vell is the Kree defector who powers Carol and names her legacy, betraying his empire for Earth.' },
  { zh: 'MCU 里她化作劳森博士，以光速引擎的遗志连接起卡罗尔与斯克鲁尔两族，是《惊奇队长》的精神核心。', en: 'As Dr. Lawson in the MCU, her light-speed legacy links Carol and the Skrulls — Captain Marvel\'s spiritual core.' },
]);
bio('ch-maria-hill', [
  { zh: '玛丽亚·希尔是神盾局的副局长：冷静高效的特工精英，尼克·弗瑞最信任的副手。', en: 'Maria Hill, S.H.I.E.L.D.\\\'s deputy director, is the cool, efficient agent Nick Fury trusts most.' },
  { zh: '她在《复联4》后继续参与弗瑞的隐秘行动，于《秘密入侵》中被斯克鲁人冒充的弗瑞处决，悲壮退场。', en: 'She dies in Secret Invasion — shot by a Skrull posing as Fury.' },
  { zh: '希尔是弗瑞最锋利的执行者：冷静、高效、随时准备接手任何烂摊子。', en: 'Hill is Fury\'s sharpest operative — cool, efficient, ever ready for the next disaster.' },
  { zh: '她的猝然离世让《秘密入侵》的背叛主题有了实体重量，也让观众怀念那个‘靠谱的副局长’。', en: 'Her abrupt death gives Secret Invasion\'s betrayal tangible weight — audiences mourn the reliable deputy.' },
]);
bio('ch-mbaku', [
  { zh: '姆巴库是瓦坎达贾巴里部落的首领：曾挑战黑豹王位失败，却率部落支持特查拉。', en: 'M\\\'Baku, leader of Wakanda\\\'s Jabari tribe, once challenged for the throne — then pledged his warriors to T\\\'Challa.' },
  { zh: '《黑豹2》中他成为议政首领，在特查拉葬礼与对塔洛坎战争的关键时刻都是瓦坎达的定海神针。', en: 'In Wakanda Forever he becomes a pillar of the realm, steadying it through war and grief.' },
  { zh: '姆巴库的巨力与山岳般的体格让他两次挑战黑豹王座，是瓦坎达少数敢对王室说不的人。', en: 'M\'Baku\'s raw power twice challenges the Panther throne — among the few Wakandans who talk back to royalty.' },
  { zh: '从敌人到盟友再到摄政重臣，他始终以自己的方式忠于瓦坎达，而非忠于某一位王。', en: 'Enemy to ally to regent, he stays loyal to Wakanda itself — never merely to a single king.' },
]);
bio('ch-melina-vostokoff', [
  { zh: '梅琳娜·沃斯托科夫是《黑寡妇》中的铁娘子：红房子的资深寡妇与生物化学家，曾与娜塔莎一家伪装潜伏美国。', en: 'Melina Vostokoff, the Iron Maiden of Black Widow, is a Red Room scientist who once posed as Natasha\\\'s mother in America.' },
  { zh: '她研制了寡妇解毒剂并暗中破坏红房子，最终与娜塔莎、叶莲娜重逢并肩摧毁德雷科夫。', en: 'She sabotages the Red Room with her antidote and reunites with Natasha and Yelena to end Dreykov.' },
  { zh: '梅琳娜是红房子的科学家兼杀手，铁娘子之名背后是对体制既顺从又暗自破坏的双面人生。', en: 'Scientist and killer, the Iron Maiden plays Red Room loyalist while quietly undermining it.' },
  { zh: '她研制的解毒剂成为摧毁红房子的钥匙，与娜塔莎的母女重逢也补全了黑寡妇系列最缺的家庭戏。', en: 'Her antidote unlocks the Red Room\'s fall; reunion with Natasha supplies the family drama the saga lacked.' },
]);
bio('ch-michael-morbius', [
  { zh: '迈克尔·莫比亚斯是《莫比亚斯》中的活体吸血鬼：身患罕见血液病的诺奖科学家，为自救注射蝙蝠血清而变异。', en: 'Michael Morbius, the Living Vampire of his 2022 film, was a Nobel scientist with a rare blood disease — cured into a bat-like monster.' },
  { zh: '他必须吸血维生却拒绝伤害无辜，在反英雄的灰色地带与猎人搏斗。', en: 'He feeds on blood yet refuses the innocent, hunting in the gray between hero and horror.' },
  { zh: '莫比亚斯是科学家与怪物的合体：吸血维生却拒绝滥杀，在医学与诅咒之间寻找平衡。', en: 'Morbius fuses scientist and monster — feeding on blood yet refusing murder, balancing cure and curse.' },
  { zh: '作为反英雄，他比多数‘英雄’更清楚自己的阴影，也因此在灰色地带格外挣扎。', en: 'An antihero who knows his own shadow, he struggles hardest in the gray.' },
]);
bio('ch-miguel-ohara', [
  { zh: '米格尔·奥哈拉是2099年的蜘蛛侠：未来纽约的遗传学家，因基因实验事故获得蜘蛛能力。', en: 'Miguel O\\\'Hara, Spider-Man 2099, is a geneticist of future New York turned spider-hero by his own experiment.' },
  { zh: '他是《蜘蛛侠：纵横宇宙》的蜘蛛侠协会领袖，以守护「正典事件」为名追杀迈尔斯，成为多元宇宙秩序的复杂仲裁者。', en: 'In Across the Spider-Verse he leads the Spider-Society, policing the canon — and clashing with Miles.' },
  { zh: '2099 年的米格尔拥有蛛丝、尖爪与未来科技，是‘蜘蛛侠’在黑暗未来的一种可能答案。', en: 'Miguel of 2099 wields webs, claws, and future tech — one possible answer to Spider-Man in a dark tomorrow.' },
  { zh: '《纵横宇宙》里他成为蜘蛛协会的独裁式领袖，守护‘正典事件’却失去同理心，成为全片最复杂的对立面。', en: 'Across the Spider-Verse casts him as the Society\'s rigid leader — policing canon at empathy\'s cost, the film\'s most complex foil.' },
]);
bio('ch-mj-watson-mcu', [
  { zh: '米歇尔·「MJ」·琼斯-沃森是MCU的彼得·帕克同学：独立聪慧的学霸，与彼得从互相试探走到相爱。', en: 'Michelle "MJ" Jones-Watson is Peter Parker\\\'s brilliant, deadpan classmate in the MCU — and his great love.' },
  { zh: '《英雄无归》结尾她与彼得相忘于记忆魔法，那句「下次再见」成了三蛛宇宙最动人的余韵。', en: 'At No Way Home\\\'s end the spell erases her memory of him; "see you around" lingers as the saga\\\'s most aching goodbye.' },
  { zh: 'MCU 的 MJ 与漫画不同：她独立、毒舌、不等待拯救，是彼得真正的智识伙伴。', en: 'The MCU\'s MJ differs from comics — independent, deadpan, no damsel: Peter\'s true intellectual partner.' },
  { zh: '记忆被抹去后那句‘我爱你’仍未说出口的遗憾，让《英雄无归》的结局成为三代蜘蛛侠最酸涩的一笔。', en: 'The spell erasing her memory before she says \'I love you\' back makes No Way Home\'s end the saga\'s most bittersweet.' },
]);
bio('ch-moira-mactaggert', [
  { zh: '莫伊拉·麦克塔格特是X战警系列的基因学家：人类科学家却毕生研究变种人，与X教授互为知己。', en: 'Moira MacTaggert, a human geneticist, devotes her life to mutantkind — Charles Xavier\\\'s closest human peer.' },
  { zh: '漫画中她以多次重生的时间线记忆指导变种人未来，是「种族存续」背后最深层的推手之一。', en: 'In the comics her reincarnating lives steer mutant futures: the hidden architect of the species.' },
  { zh: '莫伊拉是少数知晓变种人多世真相的人类，她的研究横跨基因学与历史，是 X 教授最信任的凡人盟友。', en: 'A human who knows mutants\' reincarnation truth, Moira spans genetics and history — Xavier\'s most trusted mortal ally.' },
  { zh: '克拉科时代她以多次人生的记忆为变种人规划未来，成为‘种族存续’背后最深层的推手。', en: 'In the Krakoa era her past-life memory steers mutantkind\'s future — the hidden architect of survival.' },
]);
bio('ch-mr-fantastic-616-light', [
  { zh: '里德·理查兹（616光照会）是光照会成员神奇先生：616宇宙的弹性天才与FF领袖，参与光照会的秘密裁决。', en: 'Reed Richards of the 616 Illuminati bends reality and science alike as the Fantastic Four\\\'s leader.' },
  { zh: '他是漫威宇宙中少数在科学与道德层面同时「知道得太多」的人。', en: 'Among Marvel\\\'s smartest, he carries the burden of decisions others never see.' },
  { zh: '作为 616 光照会成员，里德常以‘大局’之名做出冷酷决定，科学家的理性在此成为双刃剑。', en: 'In the 616 Illuminati, Reed decides for the greater good — scientific reason a double-edged blade.' },
  { zh: '光照会的秘密裁决与最终失败，让漫威反思：最聪明的人组成的机构，未必是最道德的。', en: 'The Illuminati\'s fall makes Marvel ask whether the smartest council is ever the most moral.' },
]);
bio('ch-nakia', [
  { zh: '娜吉雅是瓦坎达的河族战士与多拉·米拉杰成员：特查拉的爱人，主张以人道而非复仇对待世界。', en: 'Nakia, a War Dog of Wakanda and T\\\'Challa\\\'s love, believes in outreach over vengeance.' },
  { zh: '《黑豹2》中她隐姓埋名在海地经营避难所，把特查拉之子托桑送回瓦坎达继承王位。', en: 'In Wakanda Forever she runs a Haitian sanctuary — and brings T\\\'Challa\\\'s son home to the throne.' },
  { zh: '娜基雅是瓦坎达的‘战犬’：潜伏海外收集情报，心中装的却是和平而非复仇。', en: 'Nakia is Wakanda\'s War Dog — an overseas spy whose heart carries peace, not vengeance.' },
  { zh: '《黑豹2》中她在海地守护避难所并把特查拉之子带回王国，延续了瓦坎达最温柔的传承。', en: 'In Wakanda Forever she shelters refugees in Haiti and returns T\'Challa\'s son — Wakanda\'s gentlest legacy.' },
]);
bio('ch-ned-leeds', [
  { zh: '内德·利兹是MCU蜘蛛侠的死党：彼得的「椅子管理员」，无意中发现了他的双重身份并全力支持。', en: 'Ned Leeds, Peter Parker\\\'s MCU best friend, is his "guy in the chair" — discovering and embracing the secret identity.' },
  { zh: '《英雄无归》的记忆魔法抹去了他与彼得的友情，多元宇宙版内德则成了「恶鬼」。', en: 'The forgetting spell severs their friendship; a multiversal Ned even becomes the Hobgoblin.' },
  { zh: '内德是彼得最忠实的‘椅中人’：不懂战斗却永远在线，是 MCU 友情戏的黄金标准。', en: 'Ned is Peter\'s loyal guy-in-the-chair — clueless in combat, forever online: the MCU\'s gold standard of friendship.' },
  { zh: '记忆魔法抹去他们的友情令人心碎，而多元宇宙里‘恶鬼’内德的存在，则给了这个角色更黑暗的可能。', en: 'The forgetting spell\'s heartbreak echoes; a multiversal Ned as Hobgoblin hints at darker roads.' },
]);
bio('ch-nightcrawler', [
  { zh: '库尔特·瓦格纳是X战警的夜行者：蓝肤、尖尾、能瞬间传送的虔诚基督徒，马戏团出身。', en: 'Kurt Wagner, the X-Men\\\'s Nightcrawler, is a blue-furred, teleporting circus mutant and devout Christian.' },
  { zh: '他以乐观与信仰调和自身「恶魔外形」，是X战警中最受爱戴的成员之一。', en: 'His faith and joy transcend his demonic look — among mutantkind\\\'s most beloved.' },
  { zh: '夜行者能瞬移、攀墙，天生蓝肤与尾巴让他自幼被当作怪物，信仰却让他把‘不同’活成祝福。', en: 'Teleporting and wall-crawling with blue fur and tail, Kurt grew up feared as a monster — faith turns his difference into a blessing.' },
  { zh: '他是 X 战警的良心与笑点担当，证明真正的怪胎也能成为最温暖的天使。', en: 'The X-Men\'s conscience and comic relief, he proves the strangest among them can be its warmest angel.' },
]);
bio('ch-one-above-all', [
  { zh: '至高存在是漫威宇宙的终极创造者：凌驾于生命法庭与一切实体之上的作者化身，象征漫威编辑部本身。', en: 'The One Above All is Marvel\\\'s ultimate creator — above the Living Tribunal, an avatar of the writers themselves.' },
  { zh: '他极少现身，仅在「终极危机」般的时刻以朴素形象点拨主角，是漫威世界的形而上学顶点。', en: 'He appears only in supreme moments, a quiet figure above all cosmic law.' },
  { zh: '至高存在是漫威宇宙的作者化身：超越所有实体与法则，只在最必要的时刻现身。', en: 'The One Above All is Marvel\'s author-avatar — beyond entities and law, appearing only when truly necessary.' },
  { zh: '他对银影侠的一席话揭示漫威的终极信念：宇宙的答案不是力量，而是存在的意义本身。', en: 'His word to the Surfer reveals Marvel\'s deepest creed — the cosmos answers not with power but with meaning.' },
]);
bio('ch-peni-parker', [
  { zh: '佩妮·帕克是《蜘蛛侠：平行宇宙》中的机娘蜘蛛侠：来自未来东京，与父亲留下的机甲SP//dr神经相连。', en: 'Peni Parker of Spider-Verse is Tokyo\\\'s mecha Spider — neurally linked to SP//dr, her father\\\'s robot.' },
  { zh: '她与机甲并肩作战，是蜘蛛军团中最具科幻感的成员。', en: 'Fighting inside the machine, she brings anime flair to the Spider-Society.' },
  { zh: '佩妮与机甲 SP//dr 神经相连，人机一体让她既是驾驶员也是机甲本身。', en: 'Peni links neurally with the SP//dr armor — pilot and machine, one being.' },
  { zh: '《平行宇宙》中她的机械蜘蛛让蜘蛛军团拥有动漫维度，也延续了‘帕克家女孩也能继承’的主题。', en: 'Her mecha spider adds an anime dimension to the Society — proof Parker women inherit too.' },
]);
bio('ch-phastos', [
  { zh: '法斯托斯是永恒族中的发明家：能凭空锻造武器与科技，是人类科技文明的隐藏推手。', en: 'Phastos of the Eternals forges technology from nothing — the hidden hand behind human invention.' },
  { zh: '《永恒族》中他与凡人丈夫本相守一生，裁决日时他制造的武器却险些酿成内战。', en: 'In Eternals he lives a human life with husband Ben until judgment day forces his hand.' },
  { zh: '法斯托斯是永恒族的发明之神，人类每一次技术跃迁背后都有他隐形的推手。', en: 'Phastos, the Eternals\' inventor, is the hidden hand behind every human technological leap.' },
  { zh: '与凡人丈夫本相守一生的他，证明即使拥有神的力量，平凡的爱仍是值得守护的奇迹。', en: 'A lifetime with husband Ben shows that even gods find ordinary love the miracle worth guarding.' },
]);
bio('ch-psylocke', [
  { zh: '贝琪·布拉多克是X战警的灵蝶：日裔英国贵族的双重身份，精通忍术与心灵之刃。', en: 'Betsy Braddock, the X-Man Psylocke, wields psychic blades and ninja arts across dual identities.' },
  { zh: '她以武士精神行走于X战警与刺客之间，是变种人世界最锋利的刃。', en: 'Samurai-spirited, she walks the line between X-Man and assassin.' },
  { zh: '灵蝶以心灵之刃斩开精神防御，忍术与武士道让她既是刺客也是艺术家。', en: 'Psylocke\'s psychic knife severs mental defenses; ninjutsu and bushido make her assassin and artist in one.' },
  { zh: '英日双重身份的挣扎、与死亡和解的经历，让她成为 X 战警中最具东方哲思的战士。', en: 'Torn between British and Japanese selves, shaped by death itself, she is the X-Men\'s most Eastern-minded warrior.' },
]);
bio('ch-quentin-beck', [
  { zh: '昆汀·贝克是《蜘蛛侠：英雄远征》的神秘客：斯塔克工业的前特效师，心怀怨恨，用全息科技编织「元素众」骗局。', en: 'Quentin Beck, Mysterio of Far From Home, was a Stark Industries VFX artist who faked the Elementals with holograms.' },
  { zh: '他骗取钢铁侠遗产、设计陷害蜘蛛侠，最终被自己的幻术反杀，临终遗言却让彼得的身份暴露给全世界。', en: 'He steals Tony\\\'s legacy and frames Peter — dying by his own illusions, yet exposing Peter\\\'s identity.' },
  { zh: '神秘客的‘魔法’全靠全息投影与特效，他的骗局是对‘眼见为实’最彻底的嘲讽。', en: 'Mysterio\'s \'sorcery\' is pure hologram and VFX — a con that mocks believing your eyes.' },
  { zh: '《英雄远征》里他临死前公开彼得身份的报复，把‘被欺骗的大众’也写进了 MCU 的代价清单。', en: 'Far From Home\'s dying revenge — exposing Peter — charges the deceived public into the MCU\'s ledger.' },
]);
bio('ch-quentin-beck-616', [
  { zh: '昆汀·贝克（616漫画）是经典神秘客：电影特效师出身的罪犯，以灯光幻影制造「魔法」假象，是蜘蛛侠的宿敌之一。', en: 'Quentin Beck of the comics is the classic Mysterio — a film-effects genius faking sorcery with light and smoke.' },
  { zh: '他是不靠超能力、仅凭演技与科技的凡人反派，险恶六人组的元老。', en: 'No powers, pure performance: a founding Sinister Six showman.' },
  { zh: '漫画神秘客是特效师出身的骗子，以灯光烟雾制造神迹，是蜘蛛侠宿敌中最‘不超能’的一位。', en: 'Comics\' Mysterio is a VFX artist faking miracles with light and smoke — Spider-Man\'s least superpowered nemesis.' },
  { zh: '他对‘被认可’的病态渴望让他屡败屡战，也让他成为险恶六人组里最会‘表演’的元老。', en: 'His craving for recognition fuels endless returns — the Sinister Six\'s most theatrical founder.' },
]);
bio('ch-red-skull', [
  { zh: '约翰·施密特是红骷髅：纳粹科学部首领，因未完成版血清而面容尽毁，却因此获得不死之身与九头蛇的创立。', en: 'Johann Schmidt, the Red Skull, led Nazi science and HYDRA — his flawed serum burned his face but made him ageless.' },
  { zh: '他是美队的宿敌；《复联3》中他以灵魂宝石看守者身份再现，指引灭霸完成以爱换石的献祭。', en: 'Captain America\\\'s nemesis, he reappears in Infinity War as the Soul Stone\\\'s keeper.' },
  { zh: '红骷髅的失败源于傲慢：他追求‘完美人类’，却把自己烧成了最不完美的怪物。', en: 'Red Skull\'s fall is pride — chasing the perfect human, he scorched himself into the least perfect monster.' },
  { zh: '《复联3》里他以灵魂宝石看守者的面目再现，用最平静的语气说出最残酷的规则。', en: 'As the Soul Stone\'s keeper in Infinity War, he speaks the cruelest rules in the calmest voice.' },
]);
bio('ch-riri-williams', [
  { zh: '瑞里·威廉姆斯是《黑豹2》中的钢铁之心：麻省理工的天才少女，逆向拆解斯塔克科技造出第一套战甲。', en: 'Riri Williams, Ironheart of Wakanda Forever, is an MIT prodigy who reverse-engineered Stark tech into her own suit.' },
  { zh: '瓦坎达战后她获赠振金与实验室，踏上继承钢铁侠衣钵的道路。', en: 'Gifted vibranium and a lab by Shuri, she rises as Iron Man\\\'s intellectual heir.' },
  { zh: '瑞里在宿舍里逆向拆解斯塔克科技造出战甲，天才不认门第，只认电路。', en: 'Riri reverse-engineered Stark tech in her dorm — genius knowing no pedigree, only circuits.' },
  { zh: '《黑豹2》中她在瓦坎达获得振金与工坊，正接过‘用头脑改变世界’的钢铁侠衣钵。', en: 'Wakanda Forever grants her vibranium and a lab — Iron Man\'s mind-driven mantle, next generation.' },
]);
bio('ch-sabretooth', [
  { zh: '维克托·克里德是剑齿虎：金刚狼的宿敌兼同母异父兄弟，同样拥有再生因子与野兽般的爪牙。', en: 'Victor Creed, Sabretooth, is Wolverine\\\'s feral arch-enemy — and brother — sharing his healing and claws.' },
  { zh: '他凶残而纯粹，多次追杀金刚狼，是X战警宇宙最著名的宿命对决之一。', en: 'Pure predator, he hunts Logan across decades in mutantkind\\\'s most famous blood-feud.' },
  { zh: '剑齿虎的凶残与再生让他成为金刚狼的影子：共享血缘，却选择成为纯粹的野兽。', en: 'Sabretooth\'s savagery and healing mirror Wolverine — same blood, yet he chose to be the pure beast.' },
  { zh: '两人跨越百年的宿敌循环，是 X 战警世界里‘命运与自由’最血腥的注脚。', en: 'Their century-spanning feud is the X-Men world\'s bloodiest note on fate versus choice.' },
]);
bio('ch-sentry-bob', [
  { zh: '罗伯特·雷诺兹是漫画中的哨兵：喝下「黄金哨兵」血清后拥有「一百万颗太阳爆炸」之力，却因此诞生了黑暗人格「虚无」。', en: 'Robert Reynolds, the Sentry, drank the Golden Sentry serum and gained the power of a million exploding suns — birthing his dark self, the Void.' },
  { zh: '他是漫威最强的英雄也是最脆弱的定时炸弹，象征力量与恐惧的一体两面。', en: 'Marvel\\\'s mightiest hero and most fragile bomb: strength and terror in one.' },
  { zh: '哨兵拥有‘一百万颗太阳’的力量，却连自己的黑暗面‘虚无’都无法控制——最强即最脆。', en: 'The Sentry wields a million suns yet cannot govern his dark self, the Void — the strongest also the most fragile.' },
  { zh: '他与虚无的共生关系是漫威对‘超能力与心理疾病’最极端的隐喻。', en: 'His bond with the Void is Marvel\'s most extreme metaphor for power and mental illness.' },
]);
bio('ch-shang-chi-616', [
  { zh: '尚气（616漫画）是漫威经典武术英雄：自幼被父亲傅满洲训练成杀手，后叛出师门在美国以功夫行侠。', en: 'Shang-Chi of Earth-616 is Marvel\\\'s classic martial artist — trained as an assassin by his father, then turned hero in America.' },
  { zh: '他是漫画中首批亚裔超级英雄之一，近年漫画中更与特工机构合作探索自己的身世。', en: 'Among comics\\\' first Asian superheroes, his modern runs dig into legacy and spycraft.' },
  { zh: '漫画尚气由父亲培养成杀手，叛出后以功夫行侠，是漫威最早、最纯粹的武术英雄。', en: 'Comics\' Shang-Chi, trained assassin turned hero, is Marvel\'s earliest pure martial artist.' },
  { zh: '近年漫画让他融入特工与家族秘密，在新时代重新定义‘功夫’与‘遗产’。', en: 'Modern runs weave him into spycraft and family secrets — redefining kung fu and legacy for a new era.' },
]);
bio('ch-sharon-carter', [
  { zh: '莎伦·卡特是佩吉·卡特的侄女：神盾局特工，曾以护士身份掩护美国队长并与之相爱。', en: 'Sharon Carter, Peggy\\\'s niece and S.H.I.E.L.D. agent, loved Steve Rogers while nursing him undercover.' },
  { zh: '《美队3》后她被通缉流亡，《猎鹰与冬兵》中以「权力掮客」身份操控马德里坡，灰色立场令人生畏。', en: 'Wanted after Civil War, she resurfaces in The Falcon and the Winter Soldier as the Power Broker of Madripoor.' },
  { zh: '莎伦继承了姑姑佩吉的特工基因，冷静、专业，能为了任务潜入最危险的黑暗。', en: 'Sharon inherits Aunt Peggy\'s agent DNA — cool, professional, willing to dive into the darkest covers.' },
  { zh: '《猎鹰与冬兵》里她以‘权力掮客’身份掌管马德里坡，从体制英雄走向灰色地带，是 MCU 最耐人寻味的转身。', en: 'As the Power Broker of Madripoor she trades institutional heroism for the gray — the MCU\'s most intriguing pivot.' },
]);
bio('ch-spider-man-1602', [
  { zh: '彼得·帕克（1602宇宙）是尼尔·盖曼《漫威1602》中的蜘蛛侠：伊丽莎白时代宫廷中的少年侍从。', en: 'Peter Parker of Earth-1602, Neil Gaiman\\\'s Marvel 1602, is a page in Elizabethan court — bitten by a spider from the future.' },
  { zh: '在被奇异博士「魔法」辐射的世界里，他被一只来自未来的蜘蛛咬伤，成为都铎王朝的墙上爬行者。', en: 'In a world of Tudor intrigue he becomes that era\\\'s wall-crawler.' },
  { zh: '1602 宇宙的彼得在伊丽莎白宫廷中被未来之蛛咬伤，成为都铎时代的爬墙者。', en: 'Earth-1602\'s Peter, bitten by a future spider in Elizabethan court, becomes that era\'s wall-crawler.' },
  { zh: '盖曼笔下的他让‘蜘蛛侠’褪去现代科技，回归最朴素的英雄本义。', en: 'Gaiman\'s take strips Spider-Man of modern tech — back to heroism\'s bare essentials.' },
]);
bio('ch-spider-noir', [
  { zh: '暗影蜘蛛侠是《蜘蛛侠：平行宇宙》中的黑白侦探版彼得·帕克：1933年大萧条纽约的黑帮克星。', en: 'Spider-Man Noir is the black-and-white, trench-coated Peter Parker of 1933 — gunning down mobsters in Depression-era New York.' },
  { zh: '他冷酷寡言、以枪与影作战，是蜘蛛军团中最「黑色电影」的存在。', en: 'Cold and cinematic, he is the Spider-Society\\\'s most hard-boiled member.' },
  { zh: '暗影蜘蛛侠以大萧条纽约为战场，黑风衣与左轮让他的‘蜘蛛’染上黑色电影的血色。', en: 'Noir Spider fights Depression-era New York in trench coat and revolver — a spider dipped in noir blood.' },
  { zh: '《平行宇宙》中他与主流蜘蛛侠的冷热反差，让‘同一个名字的无数可能’变得具体。', en: 'Alongside brighter Spiders in the film, his chill contrast makes infinite variants tangible.' },
]);
bio('ch-sprite', [
  { zh: '斯派特是永恒族中的「小精灵」：能制造幻象，却因永远长不大的外形而深陷身份困惑。', en: 'Sprite of the Eternals weaves illusions but never grows up — trapped in a child\\\'s body for millennia.' },
  { zh: '《永恒族》中他嫉妒瑟西的凡人爱情，向伊卡瑞斯泄密酿成悲剧；影片结尾他接受现实，由瑟西用宇宙能量赐予凡人之躯。', en: 'In Eternals her jealousy of Sersi\\\'s mortal love drives tragedy; at the end Sersi grants her humanity.' },
  { zh: '斯派特的幻象术能欺骗神明，却骗不了自己永远停在童年的现实——永恒族里最年轻的也是最痛的。', en: 'Sprite\'s illusions fool gods yet not herself — forever a child in an Eternal\'s body: the youngest and most hurting.' },
  { zh: '嫉妒与背叛让她一度站在悲剧一侧，而瑟西赐予的凡人终老，反而成了她最温柔的救赎。', en: 'Jealousy drives her toward tragedy; Sersi\'s gift of mortal aging becomes her gentlest redemption.' },
]);
bio('ch-squirrel-girl', [
  { zh: '多琳·格林是松鼠女孩：拥有松鼠般的力量、敏捷与尾巴，能与松鼠交流。她最著名的战绩是「正面击败灭霸与毁灭博士」。', en: 'Doreen Green, Squirrel Girl, has squirrel strength, agility, a tail — and a talent for defeating cosmic villains.' },
  { zh: '她以「不可战胜」的喜剧设定成为漫威最反套路的英雄，常驻《无敌松鼠女孩》系列。', en: 'Her claim to fame: beating Thanos and Doctor Doom outright. Marvel\\\'s most unstoppable joke-turned-hero.' },
  { zh: '松鼠女孩拥有松鼠的力量、敏捷与大军，却以‘打败过灭霸与毁灭博士’的离谱战绩闻名。', en: 'Squirrel Girl wields squirrel strength and armies — famous for improbably defeating Thanos and Doctor Doom.' },
  { zh: '她的存在是漫威对‘战力至上’的自嘲：真正无敌的英雄，是那个永远乐观的普通人。', en: 'She is Marvel\'s satire on power-scaling — the truly invincible hero simply the most optimistic.' },
]);
bio('ch-storm', [
  { zh: '奥萝罗·门罗是X战警的风暴女：能操控天气的欧米茄级变种人，来自肯尼亚，曾为街头小偷后被X教授招入学院。', en: 'Ororo Munroe, the X-Men\\\'s Storm, commands weather as an Omega-level mutant — from Kenyan street thief to regal leader.' },
  { zh: '她成长为X战警的副队长、克拉科时代的执政官，是漫威最伟大的女性领袖之一。', en: 'She rises to deputy commander and council seat: among Marvel\\\'s greatest female leaders.' },
  { zh: '风暴女能呼风唤雨、操控天气到行星尺度，欧米茄级的力量与王者的气度让她成为 X 战警的副帅。', en: 'Storm commands weather at planetary scale — Omega power and regal poise making her the X-Men\'s deputy commander.' },
  { zh: '从开罗街头到克拉科议会，她始终是变种人世界里‘风雨之后的晴天’。', en: 'From Cairo\'s streets to Krakoa\'s council, she remains the clear sky after mutantkind\'s storms.' },
]);
bio('ch-thaddeus-ross', [
  { zh: '撒迪厄斯·罗斯是美国陆军上将：毕生追捕绿巨人，人称「雷霆」罗斯，主导了超级士兵与布鲁斯·班纳的恩怨。', en: 'Thaddeus "Thunderbolt" Ross, the U.S. general who hunted the Hulk for decades, oversaw the super-soldier program.' },
  { zh: '《美队3》后他升任国务卿推动索科维亚协议；《美队4》中他以红浩克之姿失控于白宫之战，最终被捕。', en: 'Secretary of State after Civil War, he becomes the Red Hulk in Brave New World — and is finally taken down.' },
  { zh: '罗斯将军一生追捕绿巨人，把‘班纳威胁’当成毕生事业，其偏执与军人荣誉感同样强烈。', en: 'General Ross hunts the Hulk as life\'s mission — obsession and soldier\'s honor burning equally hot.' },
  { zh: '《美队4》里他以红浩克之姿失控于白宫，把半生的怒火烧成了自己最想消灭的怪物。', en: 'Brave New World turns him into the Red Hulk rampaging at the White House — fury becoming the monster he hunted.' },
]);
bio('ch-watcher-uatu', [
  { zh: '乌阿图是观察者：来自远古种族的宇宙存在，与族人立誓只观察不干预，负责守望地球这条最重要的时间线。', en: 'Uatu the Watcher observes Earth — his people swore never to interfere, only to watch.' },
  { zh: '《假如…？》中他打破誓言干预多元宇宙，成为多元宇宙危机的叙述者与见证者。', en: 'In What If...? he breaks the oath to narrate and guard the multiverse\\\'s branches.' },
  { zh: '观察者族以‘不干预’为最高戒律，乌阿图守望地球亿万年，只在最边缘处悄然记录。', en: 'The Watchers swear non-interference; Uatu has watched Earth for eons, recording from the margins.' },
  { zh: '《假如…？》里他打破誓言，从旁观者变成多元宇宙的叙述者——打破规则的那一刻，他真正参与了故事。', en: 'What If...? has him break the oath — observer turned narrator, entering the story the moment he defies it.' },
]);
bio('ch-wong', [
  { zh: '王是卡玛泰姬的图书管理员与资深法师：古一的左右手，也是奇异博士的搭档与损友。', en: 'Wong, Kamar-Taj\\\'s librarian, is the Ancient One\\\'s right hand and Doctor Strange\\\'s friend and foil.' },
  { zh: '古一死后他留守圣所，斯特兰奇失踪五年间他代理至尊法师；终局之战后他四处开传送门救援，成为MCU最忙碌的法师。', en: 'He keeps the Sanctums through Strange\\\'s five-year dusting, acting Sorcerer Supreme — the MCU\\\'s busiest wizard.' },
  { zh: '王的法术修为深不可测，藏书楼里的数百年让他既是守护者也是活字典。', en: 'Wong\'s mastery runs deep; centuries among the library\'s tomes make him guardian and living encyclopedia.' },
  { zh: '从图书管理员到代理至尊法师，他低调扛起圣所职责，成为 MCU 最被低估却最可靠的法师。', en: 'Librarian to acting Sorcerer Supreme, he quietly holds the Sanctums — the MCU\'s most underrated wizard.' },
]);
bio('ch-yon-rogg', [
  { zh: '勇·罗格是《惊奇队长》中的克里军官：迈-威尔小队的新指挥官，信奉克里至上，视卡罗尔为「实验品」。', en: 'Yon-Rogg of Captain Marvel commands Mar-Vell\\\'s Kree squad — a supremacist who calls Carol his "experiment."' },
  { zh: '他数次与卡罗尔交锋，最终被觉醒的惊奇队长轻松击败，灰溜溜逃离地球。', en: 'He loses to her every time she believes in herself — and flees Earth humiliated.' },
  { zh: '勇·罗格的傲慢来自克里帝国的信条：他视卡罗尔为实验品，却一次次败给她的自我觉醒。', en: 'Yon-Rogg\'s arrogance springs from Kree doctrine — calling Carol his experiment, losing each time she believes.' },
  { zh: '‘不用超能力，我们来打一场’的挑战反被一拳击溃，成为《惊奇队长》最解气的一幕。', en: 'His \'no powers\' challenge ends in one punch — Captain Marvel\'s most cathartic beat.' },
]);
bio('ch-zeus', [
  { zh: '宙斯是奥林匹斯众神之王：雷神4《爱与雷霆》中他对凡人英雄傲慢轻慢，众神议会形同虚设。', en: 'Zeus, king of Olympus, greets Thor\\\'s plea with arrogance in Love and Thunder — the gods\\\' summit refusing to act.' },
  { zh: '他被格尔与雷神先后教训，最终被自己的闪电劈落王座，奥林匹斯随之蒙尘。', en: 'Humbled by Gorr and then by his own lightning, he falls from the throne as Olympus dims.' },
  { zh: '宙斯的闪电与神王威仪在 MCU 里被‘退休的天神’人设软化：他早已不把凡人当回事。', en: 'Zeus\' lightning and majesty soften in the MCU into a retired god-king who stopped taking mortals seriously.' },
  { zh: '被自己的雷电劈落王座的结局充满反讽：神不再守护时，神话也就该谢幕了。', en: 'Felled by his own bolt is rich irony — when gods stop guarding, myth itself should end.' },
]);
